class Solution:
    def minimumPossibleSum(self, n: int, target: int) -> int:
        MOD = 10**9 + 7
        k = target // 2
        if n <= k:
            return (n * (n + 1) // 2) % MOD
        else:
            sum1 = k * (k + 1) // 2
            count2 = n - k
            sum2 = count2 * target + count2 * (count2 - 1) // 2
            return (sum1 + sum2) % MOD

class Solution:
    def maxPossibleScore(self, start: List[int], d: int) -> int:
        start.sort()

        def check(m: int) -> bool:
            prev = start[0]
            for s in start[1:]:
                prev = max(s, prev + m)
                if prev > s + d:
                    return False
            return True

        low, high = 0, (start[-1] + d - start[0]) // (len(start) - 1)
        ans = 0
        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        is_target = [0] * n
        for idx in targetIndices:
            is_target[idx] = 1

        dp = [-float('inf')] * (m + 1)
        dp[0] = 0

        for i, c in enumerate(source):
            cost = is_target[i]
            for j in range(m - 1, -1, -1):
                if c == pattern[j]:
                    if dp[j] > dp[j + 1] + cost:
                        dp[j + 1] = dp[j]
                    else:
                        dp[j + 1] += cost
                else:
                    dp[j + 1] += cost
            dp[0] += cost

        return dp[m]

class Solution:
    def resultsArray(self, queries: List[List[int]], k: int) -> List[int]:
        max_heap = []
        results = []
        for x, y in queries:
            d = abs(x) + abs(y)
            if len(max_heap) < k:
                heapq.heappush(max_heap, -d)
            elif d < -max_heap[0]:
                heapq.heapreplace(max_heap, -d)

            if len(max_heap) < k:
                results.append(-1)
            else:
                results.append(-max_heap[0])
        return results

class Solution:
    def minNumberOfSeconds(self, mountainHeight: int, workerTimes: List[int]) -> int:
        low = 1
        min_w = min(workerTimes)
        high = min_w * mountainHeight * (mountainHeight + 1) // 2

        while low < high:
            mid = (low + high) // 2
            total_reduced = 0
            for t in workerTimes:
                k = mid // t
                if k > 0:
                    total_reduced += (math.isqrt(1 + 8 * k) - 1) // 2
                    if total_reduced >= mountainHeight:
                        break
            if total_reduced >= mountainHeight:
                high = mid
            else:
                low = mid + 1
        return low

class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        ans = 0
        counts = [0] * 26
        valid_count = 0
        r = 0

        for l in range(n):
            while r < n and valid_count == 0:
                idx = ord(s[r]) - 97
                counts[idx] += 1
                if counts[idx] == k:
                    valid_count += 1
                r += 1

            if valid_count > 0:
                ans += n - r + 1

            idx_l = ord(s[l]) - 97
            if counts[idx_l] == k:
                valid_count -= 1
            counts[idx_l] -= 1

        return ans

class Solution:
    def maximumTotalSum(self, maximumHeight: List[int]) -> int:
        maximumHeight.sort(reverse=True)
        total_sum = 0
        current_max = float('inf')
        for h in maximumHeight:
            assigned = min(h, current_max - 1)
            if assigned <= 0:
                return -1
            total_sum += assigned
            current_max = assigned
        return total_sum

class Solution:
    def resultsArray(self, nums: List[int], k: int) -> List[int]:
        if k == 1:
            return nums

        results = []
        consec = 1

        for i in range(len(nums)):
            if i > 0 and nums[i] == nums[i - 1] + 1:
                consec += 1
            else:
                consec = 1

            if i >= k - 1:
                if consec >= k:
                    results.append(nums[i])
                else:
                    results.append(-1)

        return results

class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        a, b = energyDrinkA[0], energyDrinkB[0]
        for drink_a, drink_b in zip(energyDrinkA[1:], energyDrinkB[1:]):
            a, b = max(a + drink_a, b), max(b + drink_b, a)
        return max(a, b)

