class Solution:
    def minDamage(self, power: int, damage: List[int], health: List[int]) -> int:
        enemies = []
        for d, h in zip(damage, health):
            t = (h + power - 1) // power
            enemies.append((d, t))

        enemies.sort(key=lambda x: x[0] / x[1], reverse=True)

        total_damage = 0
        current_sum = sum(damage)
        for d, t in enemies:
            total_damage += current_sum * t
            current_sum -= d

        return total_damage

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def check(x: int, y: int) -> bool:
            s1, s2 = str(x), str(y)
            max_len = max(len(s1), len(s2))
            s1 = s1.zfill(max_len)
            s2 = s2.zfill(max_len)
            diff = [i for i in range(max_len) if s1[i] != s2[i]]
            if len(diff) == 0:
                return True
            if len(diff) == 2:
                i, j = diff
                return s1[i] == s2[j] and s1[j] == s2[i]
            return False

        ans = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if check(nums[i], nums[j]):
                    ans += 1
        return ans

class Solution:
    def stringHash(self, s: str, k: int) -> str:
        res = []
        for i in range(0, len(s), k):
            block = s[i:i+k]
            total = sum(ord(c) - ord('a') for c in block)
            res.append(chr(ord('a') + (total % 26)))
        return "".join(res)

