class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        ans = 0
        n = len(s)
        for i in range(n):
            c0 = c1 = 0
            for j in range(i, n):
                if s[j] == '0':
                    c0 += 1
                else:
                    c1 += 1
                if c0 <= k or c1 <= k:
                    ans += 1
