class Solution:
    def countGoodIntegers(self, n: int, k: int) -> int:
        half_len = (n + 1) // 2
        start = 10 ** (half_len - 1)
        end = 10 ** half_len

        seen_multisets = set()

        for p in range(start, end):
            s = str(p)
            if n % 2 == 0:
                pal_str = s + s[::-1]
            else:
                pal_str = s + s[:-1][::-1]

            if int(pal_str) % k == 0:
                seen_multisets.add("".join(sorted(pal_str)))

        total_good = 0
        for multiset in seen_multisets:
            counts = collections.Counter(multiset)
            ways = (n - counts['0']) * math.factorial(n - 1)
            for cnt in counts.values():
                ways //= math.factorial(cnt)
            total_good += ways

        return total_good

class Solution:
    def maximumValueSum(self, board: List[List[int]]) -> int:
        m, n = len(board), len(board[0])
        best = []
        for r in range(m):
            best.append(heapq.nlargest(3, ((board[r][c], c) for c in range(n))))

        ans = -float('inf')
        for r1, r2, r3 in itertools.combinations(range(m), 3):
            for v1, c1 in best[r1]:
                for v2, c2 in best[r2]:
                    if c1 == c2:
                        continue
                    for v3, c3 in best[r3]:
                        if c3 != c1 and c3 != c2:
                            val = v1 + v2 + v3
                            if val > ans:
                                ans = val
        return ans

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        if k == 1 or k == 3 or k == 9:
            return "9" * n

        if k == 2:
            if n == 1:
                return "8"
            elif n == 2:
                return "88"
            else:
                return "8" + "9" * (n - 2) + "8"

        if k == 4:
            if n <= 3:
                return "8" * n
            else:
                return "88" + "9" * (n - 4) + "88"

        if k == 5:
            if n == 1:
                return "5"
            elif n == 2:
                return "55"
            else:
                return "5" + "9" * (n - 2) + "5"

        if k == 6:
            if n == 1:
                return "6"
            elif n == 2:
                return "66"
            elif n % 2 == 1:
                half = (n - 3) // 2
                return "8" + "9" * half + "8" + "9" * half + "8"
            else:
                half = (n - 4) // 2
                return "8" + "9" * half + "77" + "9" * half + "8"

        if k == 8:
            if n <= 5:
                return "8" * n
            else:
                return "888" + "9" * (n - 6) + "888"

        if k == 7:
            if n == 1:
                return "7"
            if n == 2:
                return "77"

            # Precompute powers of 10 mod 7
            p10 = [1] * (n + 1)
            for i in range(1, n + 1):
                p10[i] = (p10[i - 1] * 10) % 7

            # Total mod with all 9s
            base_mod = 0
            for i in range(n):
                base_mod = (base_mod + 9 * p10[i]) % 7

            if n % 2 == 1:
                mid = n // 2
                for d in range(9, -1, -1):
                    diff = (9 - d) * p10[mid] % 7
                    if (base_mod - diff) % 7 == 0:
                        half = mid
                        return "9" * half + str(d) + "9" * half
            else:
                mid1 = n // 2 - 1
                mid2 = n // 2
                factor = (p10[mid1] + p10[mid2]) % 7
                for d in range(9, -1, -1):
                    diff = (9 - d) * factor % 7
                    if (base_mod - diff) % 7 == 0:
                        half = mid1
                        return "9" * half + str(d) * 2 + "9" * half

        return ""

