class Solution:
    def getFinalState(self, nums: List[int], k: int, multiplier: int) -> List[int]:
        h = [(val, i) for i, val in enumerate(nums)]
        heapq.heapify(h)
        for _ in range(k):
            val, i = heapq.heappop(h)
            nums[i] = val * multiplier
            heapq.heappush(h, (nums[i], i))
        return nums

class Solution:
    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        m, n = len(grid), len(grid[0])
        dist = [[float('inf')] * n for _ in range(m)]
        dist[0][0] = grid[0][0]
        dq = collections.deque([(0, 0)])

        while dq:
            r, c = dq.popleft()
            if r == m - 1 and c == n - 1:
                break
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    cost = grid[nr][nc]
                    if dist[r][c] + cost < dist[nr][nc]:
                        dist[nr][nc] = dist[r][c] + cost
                        if cost == 0:
                            dq.appendleft((nr, nc))
                        else:
                            dq.append((nr, nc))

        return dist[m - 1][n - 1] < health

class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        n = len(target)
        max_L = [0] * n

        def get_z(s):
            m = len(s)
            z = [0] * m
            l, r = 0, 0
            for i in range(1, m):
                if i <= r:
                    z[i] = min(r - i + 1, z[i - l])
                while i + z[i] < m and s[z[i]] == s[i + z[i]]:
                    z[i] += 1
                if i + z[i] - 1 > r:
                    l = i
                    r = i + z[i] - 1
            return z

        for w in words:
            s = w + '#' + target
            z = get_z(s)
            m = len(w)
            for i in range(n):
                match_len = z[m + 1 + i]
                if match_len > max_L[i]:
                    max_L[i] = match_len

        ans = 0
        cur_end = 0
        farthest = 0

        for i in range(n):
            farthest = max(farthest, i + max_L[i])
            if i == cur_end:
                if farthest == i:
                    return -1
                ans += 1
                cur_end = farthest
                if cur_end >= n:
                    return ans

        return -1

class Solution:
    def maxMoves(self, kx: int, ky: int, positions: List[List[int]]) -> int:
        n = len(positions)
        pts = positions + [[kx, ky]]

        # BFS to find shortest knight distance from each point to all other points
        dirs = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        dist = [[0] * (n + 1) for _ in range(n + 1)]

        for i in range(n + 1):
            sx, sy = pts[i]
            d = [[-1] * 50 for _ in range(50)]
            d[sx][sy] = 0
            q = collections.deque([(sx, sy)])
            while q:
                x, y = q.popleft()
                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < 50 and 0 <= ny < 50 and d[nx][ny] == -1:
                        d[nx][ny] = d[x][y] + 1
                        q.append((nx, ny))
            for j in range(n + 1):
                dist[i][j] = d[pts[j][0]][pts[j][1]]

        memo = {}

        def solve(mask, u):
            if mask == 0:
                return 0
            state = (mask, u)
            if state in memo:
                return memo[state]

            # Alice's turn if number of remaining pawns has same parity as n
            is_alice = (bin(mask).count('1') % 2 == n % 2)

            if is_alice:
                res = 0
                for v in range(n):
                    if (mask >> v) & 1:
                        res = max(res, dist[u][v] + solve(mask ^ (1 << v), v))
            else:
                res = float('inf')
                for v in range(n):
                    if (mask >> v) & 1:
                        res = min(res, dist[u][v] + solve(mask ^ (1 << v), v))

            memo[state] = res
            return res

        return solve((1 << n) - 1, n)

from bisect import bisect_left
from typing import List

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        # Augment each interval with its original index: (l, r, weight, original_index)
        sorted_intervals = sorted(
            [(l, r, w, i) for i, (l, r, w) in enumerate(intervals)],
            key=lambda x: x[1]
        )

        n = len(intervals)
        r_list = [inv[1] for inv in sorted_intervals]

        # dp[i][k] = (max_weight, tuple_of_sorted_indices)
        # Using 1-based indexing for intervals in DP table
        dp = [[(-1, ()) for _ in range(5)] for _ in range(n + 1)]
        dp[0][0] = (0, ())

        def is_better(cand, curr):
            if cand[0] != curr[0]:
                return cand[0] > curr[0]
            return cand[1] < curr[1]

        for i in range(1, n + 1):
            l, r, w, idx = sorted_intervals[i - 1]
            p = bisect_left(r_list, l)  # number of intervals strictly ending before l

            dp[i][0] = (0, ())
            for k in range(1, 5):
                # Option 1: Do not include the i-th interval
                best = dp[i - 1][k]

                # Option 2: Include the i-th interval
                if dp[p][k - 1][0] != -1:
                    cand_w = dp[p][k - 1][0] + w
                    cand_indices = tuple(sorted(dp[p][k - 1][1] + (idx,)))
                    cand = (cand_w, cand_indices)
                    if is_better(cand, best):
                        best = cand

                dp[i][k] = best

        best_overall = (-1, ())
        for k in range(1, 5):
            if is_better(dp[n][k], best_overall):
                best_overall = dp[n][k]

        return list(best_overall[1])

class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        R = len(grid)
        val_to_rows = collections.defaultdict(list)
        for r in range(R):
            for v in set(grid[r]):
                val_to_rows[v].append(r)

        dp = [-1] * (1 << R)
        dp[0] = 0

        for v in sorted(val_to_rows.keys()):
            next_dp = list(dp)
            rows = val_to_rows[v]
            for mask in range(1 << R):
                if dp[mask] == -1:
                    continue
                for r in rows:
                    if not (mask & (1 << r)):
                        new_mask = mask | (1 << r)
                        if dp[mask] + v > next_dp[new_mask]:
                            next_dp[new_mask] = dp[mask] + v
            dp = next_dp

        return max(dp)

