class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = {'a', 'e', 'i', 'o', 'u'}
        n = len(word)
        ans = 0
        for i in range(n):
            vowel_counts = {'a': 0, 'e': 0, 'i': 0, 'o': 0, 'u': 0}
            unique_vowels = 0
            consonants = 0
            for j in range(i, n):
                ch = word[j]
                if ch in vowels:
                    if vowel_counts[ch] == 0:
                        unique_vowels += 1
                    vowel_counts[ch] += 1
                else:
                    consonants += 1
                if consonants > k:
                    break
                if unique_vowels == 5 and consonants == k:
                    ans += 1
        return ans

class Solution:
    def maxPathLength(self, coordinates: List[List[int]], k: int) -> int:
        kx, ky = coordinates[k]

        before = [p for p in coordinates if p[0] < kx and p[1] < ky]
        after = [p for p in coordinates if p[0] > kx and p[1] > ky]

        def get_lis_len(pts: List[List[int]]) -> int:
            pts.sort(key=lambda p: (p[0], -p[1]))
            tails = []
            for _, y in pts:
                idx = bisect.bisect_left(tails, y)
                if idx == len(tails):
                    tails.append(y)
                else:
                    tails[idx] = y
            return len(tails)

        return 1 + get_lis_len(before) + get_lis_len(after)

class Solution:
    def validSubstringCount(self, word1: str, word2: str) -> int:
        need = collections.Counter(word2)
        missing = len(need)
        window = collections.defaultdict(int)

        ans = 0
        l = 0
        n = len(word1)

        for r, ch in enumerate(word1):
            window[ch] += 1
            if ch in need and window[ch] == need[ch]:
                missing -= 1

            while missing == 0:
                ans += n - r
                left_ch = word1[l]
                if left_ch in need and window[left_ch] == need[left_ch]:
                    missing += 1
                window[left_ch] -= 1
                l += 1

        return ans

