class Solution:
    def minStartingIndex(self, s: str, pattern: str) -> int:
        def z_function(st: str) -> list[int]:
            n = len(st)
            z = [0] * n
            l, r = 0, 0
            for i in range(1, n):
                if i <= r:
                    z[i] = min(r - i + 1, z[i - l])
                while i + z[i] < n and st[z[i]] == st[i + z[i]]:
                    z[i] += 1
                if i + z[i] - 1 > r:
                    l = i
                    r = i + z[i] - 1
            return z

        n, m = len(s), len(pattern)
        z1 = z_function(pattern + '#' + s)
        z2 = z_function(pattern[::-1] + '#' + s[::-1])

        for i in range(n - m + 1):
            l1 = z1[m + 1 + i]
            l2 = z2[m + 1 + (n - i - m)]
            if l1 + l2 >= m - 1:
                return i

        return -1

class Solution:
    def gcdValues(self, nums: List[int], queries: List[int]) -> List[int]:
        max_val = max(nums)
        freq = [0] * (max_val + 1)
        for x in nums:
            freq[x] += 1

        cnt = [0] * (max_val + 1)
        for i in range(1, max_val + 1):
            for j in range(i, max_val + 1, i):
                cnt[i] += freq[j]

        exact = [0] * (max_val + 1)
        for i in range(max_val, 0, -1):
            total_pairs = cnt[i] * (cnt[i] - 1) // 2
            for j in range(2 * i, max_val + 1, i):
                total_pairs -= exact[j]
            exact[i] = total_pairs

        pref = [0] * (max_val + 1)
        for i in range(1, max_val + 1):
            pref[i] = pref[i - 1] + exact[i]

        return [bisect.bisect_right(pref, q) for q in queries]

class Solution:
    def validSequence(self, word1: str, word2: str) -> List[int]:
        n, m = len(word1), len(word2)
        last = [-1] * (m + 1)
        last[m] = n

        ptr = n - 1
        for j in range(m - 1, -1, -1):
            while ptr >= 0 and word1[ptr] != word2[j]:
                ptr -= 1
            last[j] = ptr
            ptr -= 1

        ans = []
        changed = False
        i = 0
        for j in range(m):
            while i < n:
                if word1[i] == word2[j]:
                    if not changed or last[j + 1] >= i + 1:
                        ans.append(i)
                        i += 1
                        break
                else:
                    if not changed and last[j + 1] >= i + 1:
                        ans.append(i)
                        changed = True
                        i += 1
                        break
                i += 1
            else:
                return []

        return ans if len(ans) == m else []

class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        dp = [0] * n
        for d in range(k):
            next_dp = [0] * n
            for dest in range(n):
                best = dp[dest] + stayScore[d][dest]
                for curr in range(n):
                    if curr != dest:
                        val = dp[curr] + travelScore[curr][dest]
                        if val > best:
                            best = val
                next_dp[dest] = best
            dp = next_dp
        return max(dp)

class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # Map: 'F' -> 0, 'W' -> 1, 'E' -> 2
        mapping = {'F': 0, 'W': 1, 'E': 2}
        alice = [mapping[c] for c in s]

        # score matrix: score[b][a] is points gained by Bob minus points gained by Alice
        # 0: F, 1: W, 2: E
        # F beats E (0 beats 2)
        # W beats F (1 beats 0)
        # E beats W (2 beats 1)
        score = [
            [0, -1, 1],   # Bob=0 (F): vs F=0, vs W=-1, vs E=1
            [1, 0, -1],   # Bob=1 (W): vs F=1, vs W=0, vs E=-1
            [-1, 1, 0]    # Bob=2 (E): vs F=-1, vs W=1, vs E=0
        ]

        # dp[b][diff + n] is the count of ways with last move `b` and score diff `diff`
        # Range of diff is -n to n, mapped to 0 to 2n
        OFFSET = n
        SIZE = 2 * n + 1

        dp = [[0] * SIZE for _ in range(3)]

        first_a = alice[0]
        for b in range(3):
            diff = score[b][first_a]
            dp[b][diff + OFFSET] = 1

        for i in range(1, n):
            a = alice[i]
            new_dp = [[0] * SIZE for _ in range(3)]
            for b in range(3):
                d = score[b][a]
                for prev_b in range(3):
                    if prev_b == b:
                        continue
                    prev_row = dp[prev_b]
                    # We want new_dp[b][diff + d + OFFSET] += prev_row[diff + OFFSET]
                    # For diff in [-n, n], if diff + d is within valid range
                    if d == 1:
                        for diff_idx in range(SIZE - 1):
                            new_dp[b][diff_idx + 1] = (new_dp[b][diff_idx + 1] + prev_row[diff_idx]) % MOD
                    elif d == -1:
                        for diff_idx in range(1, SIZE):
                            new_dp[b][diff_idx - 1] = (new_dp[b][diff_idx - 1] + prev_row[diff_idx]) % MOD
                    else: # d == 0
                        for diff_idx in range(SIZE):
                            new_dp[b][diff_idx] = (new_dp[b][diff_idx] + prev_row[diff_idx]) % MOD
            dp = new_dp

        ans = 0
        for b in range(3):
            for diff in range(OFFSET + 1, SIZE):
                ans = (ans + dp[b][diff]) % MOD

        return ans

class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        cost_matrix = [[0] * 26 for _ in range(26)]
        for u in range(26):
            for v in range(26):
                if u == v:
                    continue
                fwd_steps = (v - u) % 26
                fwd_cost = sum(nextCost[(u + k) % 26] for k in range(fwd_steps))

                bwd_steps = (u - v) % 26
                bwd_cost = sum(previousCost[(u - k) % 26] for k in range(bwd_steps))

                cost_matrix[u][v] = min(fwd_cost, bwd_cost)

        total_cost = 0
        for sc, tc in zip(s, t):
            u = ord(sc) - ord('a')
            v = ord(tc) - ord('a')
            total_cost += cost_matrix[u][v]

        return total_cost

