        count = collections.Counter(nums)
        ans = -float('inf')
        for y in nums:
            rem = total_sum - y
            if rem % 2 == 0:
                x = rem // 2
                if (x != y and count[x] >= 1) or (x == y and count[x] >= 2):
                    if y > ans:
                        ans = y
        return ans

