        MOD = 1_000_000_007
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1

        for _ in range(t):
            z = cnt[25]
            cnt = [z % MOD, (cnt[0] + z) % MOD] + cnt[1:25]

        return sum(cnt) % MOD

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Precompute steps to reduce each count to 1
        steps = [0] * (n + 1)
        for c in range(2, n + 1):
            steps[c] = 1 + steps[c.bit_count()]

        # Precompute combinations C(n, k) % MOD
        C = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        ways = [0] * (n + 1)
        cnt1 = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = n - 1 - i
                for r in range(rem + 1):
                    ways[cnt1 + r] = (ways[cnt1 + r] + C[rem][r]) % MOD
                cnt1 += 1

        ans = 0
        for c in range(1, n + 1):
            if steps[c] <= k - 1:
                ans = (ans + ways[c]) % MOD

        return ans

class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        best_index = events[0][0]
        max_time = events[0][1]

        for i in range(1, len(events)):
            diff = events[i][1] - events[i - 1][1]
            idx = events[i][0]
            if diff > max_time:
                max_time = diff
                best_index = idx
            elif diff == max_time:
                best_index = min(best_index, idx)

        return best_index

class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        score = 0
        for i, char in enumerate(s):
            c_idx = ord(char) - ord('a')
            mirror_idx = 25 - c_idx
            if stacks[mirror_idx]:
                j = stacks[mirror_idx].pop()
                score += i - j
            else:
                stacks[c_idx].append(i)
        return score

