class Solution:
    def maxRemoval(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        queries_by_start = [[] for _ in range(n)]
        for l, r in queries:
            queries_by_start[l].append(r)

        max_heap = []
        diff = [0] * (n + 2)
        current_coverage = 0
        chosen_count = 0

        for i in range(n):
            current_coverage += diff[i]

            for r in queries_by_start[i]:
                heapq.heappush(max_heap, -r)

            while current_coverage < nums[i]:
                if not max_heap:
                    return -1
                r = -heapq.heappop(max_heap)
                if r < i:
                    continue
                current_coverage += 1
                diff[r + 1] -= 1
                chosen_count += 1

        return len(queries) - chosen_count

class Solution:
    def maxCollectedFruits(self, fruits: List[List[int]]) -> int:
        n = len(fruits)
        diag_sum = sum(fruits[i][i] for i in range(n))

        def solve(grid: List[List[int]]) -> int:
            dp = {n - 1: grid[0][n - 1]}
            for i in range(n - 2):
                next_dp = {}
                for j, val in dp.items():
                    for dj in (-1, 0, 1):
                        nj = j + dj
                        if nj > i + 1 and nj < n:
                            next_dp[nj] = max(next_dp.get(nj, -1), val + grid[i + 1][nj])
                dp = next_dp
            return dp.get(n - 1, 0)

        transposed = [[fruits[j][i] for j in range(n)] for i in range(n)]
        return diag_sum + solve(fruits) + solve(transposed)

class Solution:
    def findMinimumTime(self, strength: List[int], K: int) -> int:
        n = len(strength)
        dp = [float('inf')] * (1 << n)
        dp[0] = 0

        for mask in range(1 << n):
            X = 1 + mask.bit_count() * K
            for j in range(n):
                if not (mask & (1 << j)):
                    time_needed = (strength[j] + X - 1) // X
                    nxt = mask | (1 << j)
                    if dp[mask] + time_needed < dp[nxt]:
                        dp[nxt] = dp[mask] + time_needed

        return dp[(1 << n) - 1]

