class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        dp = [[float('inf')] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0

        for x in nums:
            options = [(0, 0, x), (1, 0, (x + 1) // 2)]
            if x >= k:
                options.append((0, 1, x - k))

            both_val = float('inf')
            if (x + 1) // 2 >= k:
                both_val = min(both_val, (x + 1) // 2 - k)
            if x >= k:
                both_val = min(both_val, (x - k + 1) // 2)
            if both_val != float('inf'):
                options.append((1, 1, both_val))

            new_dp = [[float('inf')] * (op2 + 1) for _ in range(op1 + 1)]
            for c1 in range(op1 + 1):
                for c2 in range(op2 + 1):
                    if dp[c1][c2] == float('inf'):
                        continue
                    for dc1, dc2, val in options:
                        nc1, nc2 = c1 + dc1, c2 + dc2
                        if nc1 <= op1 and nc2 <= op2:
                            if dp[c1][c2] + val < new_dp[nc1][nc2]:
                                new_dp[nc1][nc2] = dp[c1][c2] + val
            dp = new_dp

        return min(dp[c1][c2] for c1 in range(op1 + 1) for c2 in range(op2 + 1))

