class Solution:
    def minDifference(self, nums: List[int]) -> int:
        n = len(nums)

        # Check if all elements are -1
        if all(x == -1 for x in nums):
            return 0

        base_diff = 0
        for i in range(n - 1):
            if nums[i] != -1 and nums[i + 1] != -1:
                base_diff = max(base_diff, abs(nums[i] - nums[i + 1]))

        # Find segments of -1s
        segments = []
        i = 0
        while i < n:
            if nums[i] == -1:
                j = i
                while j < n and nums[j] == -1:
                    j += 1
                left_neighbor = nums[i - 1] if i > 0 else None
                right_neighbor = nums[j] if j < n else None
                segments.append((j - i, left_neighbor, right_neighbor))
                i = j
            else:
                i += 1

        def can_cover(intervals, require_dist, d):
            if not intervals:
                return True
            for l, r in intervals:
                if l > r:
                    return False
            r_min = min(r for l, r in intervals)
            x = r_min
            uncovered = [iv for iv in intervals if not (iv[0] <= x <= iv[1])]
            if not uncovered:
                return True
            l_prime_max = max(l for l, r in uncovered)
            r_prime_min = min(r for l, r in uncovered)
            if l_prime_max > r_prime_min:
                return False
            if require_dist:
                return l_prime_max - x <= d
            return True

        def check(d):
            if d < base_diff:
                return False

            # Case A: with transition (|x - y| <= d)
            intervals_a = []
            for length, left, right in segments:
                if length == 1:
                    if left is not None and right is not None:
                        intervals_a.append((max(left, right) - d, min(left, right) + d))
                    elif left is not None:
                        intervals_a.append((left - d, left + d))
                    elif right is not None:
                        intervals_a.append((right - d, right + d))
                else:
                    if left is not None:
                        intervals_a.append((left - d, left + d))
                    if right is not None:
                        intervals_a.append((right - d, right + d))
            if can_cover(intervals_a, True, d):
                return True

            # Case B: without transition (each segment homogeneous)
            intervals_b = []
            for length, left, right in segments:
                if left is not None and right is not None:
                    intervals_b.append((max(left, right) - d, min(left, right) + d))
                elif left is not None:
                    intervals_b.append((left - d, left + d))
                elif right is not None:
                    intervals_b.append((right - d, right + d))
            if can_cover(intervals_b, False, d):
                return True

            return False

        low, high = base_diff, 10**9
        ans = high
        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1

        return ans

class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 1_000_000_007
        m, n = len(grid), len(grid[0])

        dp = [[0] * 16 for _ in range(n)]
        dp[0][grid[0][0]] = 1

        for j in range(1, n):
            val = grid[0][j]
            for x in range(16):
                dp[j][x ^ val] = dp[j - 1][x]

        for i in range(1, m):
            new_dp = [[0] * 16 for _ in range(n)]
            val = grid[i][0]
            for x in range(16):
                new_dp[0][x ^ val] = dp[0][x]

            for j in range(1, n):
                val = grid[i][j]
                for x in range(16):
                    new_dp[j][x ^ val] = (dp[j][x] + new_dp[j - 1][x]) % MOD
            dp = new_dp

        return dp[n - 1][k]

