class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        INF = float('inf')
        dp = [[[-INF] * 3 for _ in range(n)] for _ in range(m)]

        c = coins[0][0]
        dp[0][0][0] = c
        dp[0][0][1] = max(c, 0)
        dp[0][0][2] = max(c, 0)

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                c = coins[i][j]
                for k in range(3):
                    prev_max = -INF
                    if i > 0:
                        prev_max = max(prev_max, dp[i - 1][j][k])
                    if j > 0:
                        prev_max = max(prev_max, dp[i][j - 1][k])
                    if prev_max != -INF:
                        dp[i][j][k] = max(dp[i][j][k], prev_max + c)

                    if k > 0:
                        prev_max_k_minus_1 = -INF
                        if i > 0:
                            prev_max_k_minus_1 = max(prev_max_k_minus_1, dp[i - 1][j][k - 1])
                        if j > 0:
                            prev_max_k_minus_1 = max(prev_max_k_minus_1, dp[i][j - 1][k - 1])
                        if prev_max_k_minus_1 != -INF:
                            dp[i][j][k] = max(dp[i][j][k], prev_max_k_minus_1 + 0)

        return dp[m - 1][n - 1][2]

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        small_nums = [x for x in nums if x <= threshold]
        ans = len(nums) - len(small_nums)
        if not small_nums:
            return ans

        parent = {x: x for x in small_nums}
        def find(i: int) -> int:
            path = []
            while parent[i] != i:
                path.append(i)
                i = parent[i]
            for node in path:
                parent[node] = i
            return i

        def union(i: int, j: int) -> bool:
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
                return True
            return False

        comp_count = len(small_nums)
        first_div = [0] * (threshold + 1)

        for x in small_nums:
            for m in range(x, threshold + 1, x):
                if first_div[m] == 0:
                    first_div[m] = x
                else:
                    if union(x, first_div[m]):
                        comp_count -= 1

        return ans + comp_count

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = set(map(tuple, points))
        n = len(points)
        max_area = -1

        for i in range(n):
            x1, y1 = points[i]
            for j in range(n):
                x2, y2 = points[j]
                if x1 < x2 and y1 < y2:
                    if (x1, y2) in point_set and (x2, y1) in point_set:
                        corners = {(x1, y1), (x1, y2), (x2, y1), (x2, y2)}
                        valid = True
                        for x, y in points:
                            if (x, y) not in corners and x1 <= x <= x2 and y1 <= y <= y2:
                                valid = False
                                break
                        if valid:
                            area = (x2 - x1) * (y2 - y1)
                            if area > max_area:
                                max_area = area
        return max_area

