class Solution:
    def hasMatch(self, s: str, p: str) -> bool:
        p1, p2 = p.split('*')
        i1 = s.find(p1)
        if i1 == -1:
            return False
        i2 = s.find(p2, i1 + len(p1))
        return i2 != -1

class Solution:
    def countSubarrays(self, nums: List[int]) -> int:
        ans = 0
        for i in range(len(nums) - 2):
            if 2 * (nums[i] + nums[i + 2]) == nums[i + 1]:
                ans += 1
        return ans

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        def get_z(arr, start):
            m = n - start
            z = [0] * m
            l, r = 0, 0
            for i in range(1, m):
                if i <= r:
                    z[i] = min(r - i + 1, z[i - l])
                while i + z[i] < m and arr[start + z[i]] == arr[start + i + z[i]]:
                    z[i] += 1
                if i + z[i] - 1 > r:
                    l = i
                    r = i + z[i] - 1
            return z

        z0 = get_z(nums, 0)
        ans = 0

        for i in range(1, n - 1):
            z_i = get_z(nums, i)
            is_prefix1 = (z0[i] >= i)
            for j in range(i + 1, n):
                len2 = j - i
                if is_prefix1 and len2 >= i:
                    ans += 1
                elif n - j >= len2 and z_i[len2] >= len2:
                    ans += 1

        return ans

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)

        # Standard Kadane's algorithm for base answer (0 operations)
        max_so_far = nums[0]
        curr_max = nums[0]
        for x in nums[1:]:
            curr_max = max(x, curr_max + x)
            max_so_far = max(max_so_far, curr_max)
        ans = max_so_far

        # Group positions of negative numbers
        pos = collections.defaultdict(list)
        for i, x in enumerate(nums):
            if x < 0:
                pos[x].append(i)

        if not pos:
            return ans

        # Build Segment Tree
        size = 1
        while size < n:
            size *= 2
        tree = [None] * (2 * size)

        for i in range(n):
            x = nums[i]
            tree[size + i] = (x, x, x, x)  # (tot, pref, suff, best)

        def merge(L, R):
            if L is None:
                return R
            if R is None:
                return L
            L_tot, L_pref, L_suff, L_best = L
            R_tot, R_pref, R_suff, R_best = R
            tot = L_tot + R_tot
            pref = max(L_pref, L_tot + R_pref)
            suff = max(R_suff, R_tot + L_suff)
            best = max(L_best, R_best, L_suff + R_pref)
            return (tot, pref, suff, best)

        for i in range(size - 1, 0, -1):
            tree[i] = merge(tree[2 * i], tree[2 * i + 1])

        def query(l, r):
            if l > r:
                return None
            l += size
            r += size
            res_l = None
            res_r = None
            while l <= r:
                if l % 2 == 1:
                    res_l = merge(res_l, tree[l])
                    l += 1
                if r % 2 == 0:
                    res_r = merge(tree[r], res_r)
                    r -= 1
                l //= 2
                r //= 2
            return merge(res_l, res_r)

        for v, indices in pos.items():
            if len(indices) == n:
                continue
            cur_best = -float('inf')
            C = 0
            prev = -1
            for p in indices:
                if p > prev + 1:
                    tot, pref, suff, best = query(prev + 1, p - 1)
                    cur_best = max(cur_best, best, C + pref)
                    C = max(0, suff, C + tot)
                prev = p
            if n - 1 > prev:
                tot, pref, suff, best = query(prev + 1, n - 1)
                cur_best = max(cur_best, best, C + pref)
            ans = max(ans, cur_best)

        return ans

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # Group consecutive characters to get segment lengths
        groups = []
        count = 1
        for i in range(1, n):
            if s[i] == s[i - 1]:
                count += 1
            else:
                groups.append(count)
                count = 1
        groups.append(count)

        def check(k: int) -> bool:
            if k == 1:
                # Must match either '0101...' or '1010...'
                cost1 = sum(1 for i, c in enumerate(s) if c != ('0' if i % 2 == 0 else '1'))
                cost2 = sum(1 for i, c in enumerate(s) if c != ('1' if i % 2 == 0 else '0'))
                return min(cost1, cost2) <= numOps
            else:
                # Each segment of length L requires L // (k + 1) flips
                cost = sum(L // (k + 1) for L in groups)
                return cost <= numOps

        low, high = 1, n
        ans = n
        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        p1, p2, p3 = p.split('*')

        def find_all(sub: str, s: str):
            if not sub:
                return []
            n, m = len(s), len(sub)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and sub[i] != sub[j]:
                    j = pi[j - 1]
                if sub[i] == sub[j]:
                    j += 1
                pi[i] = j

            res = []
            j = 0
            for i in range(n):
                while j > 0 and s[i] != sub[j]:
                    j = pi[j - 1]
                if s[i] == sub[j]:
                    j += 1
                if j == m:
                    res.append(i - m + 1)
                    j = pi[j - 1]
            return res

        non_empty = [part for part in [p1, p2, p3] if part]
        if not non_empty:
            return 0

        pos1 = find_all(p1, s) if p1 else []
        pos2 = find_all(p2, s) if p2 else []
        pos3 = find_all(p3, s) if p3 else []

        if p1 and not pos1:
            return -1
        if p2 and not pos2:
            return -1
        if p3 and not pos3:
            return -1

        if len(non_empty) == 1:
            return len(non_empty[0])

        if len(non_empty) == 2:
            if not p1:
                A, lenA, B, lenB = pos2, len(p2), pos3, len(p3)
            elif not p2:
                A, lenA, B, lenB = pos1, len(p1), pos3, len(p3)
            else:
                A, lenA, B, lenB = pos1, len(p1), pos2, len(p2)

            ans = float('inf')
            for a in A:
                idx = bisect.bisect_left(B, a + lenA)
                if idx < len(B):
                    ans = min(ans, B[idx] + lenB - a)
            return ans if ans != float('inf') else -1

        ans = float('inf')
        for b in pos2:
            idx_a = bisect.bisect_right(pos1, b - len(p1)) - 1
            if idx_a < 0:
                continue
            a = pos1[idx_a]

            idx_c = bisect.bisect_left(pos3, b + len(p2))
            if idx_c >= len(pos3):
                continue
            c = pos3[idx_c]

            ans = min(ans, c + len(p3) - a)

        return ans if ans != float('inf') else -1

class Solution:
    def countSubstrings(self, s: str) -> int:
        dp = [[0] * d for d in range(1, 10)]
        ans = 0
        for ch in s:
            x = ord(ch) - 48
            new_dp = [[0] * d for d in range(1, 10)]
            for d in range(1, 10):
                d_idx = d - 1
                curr = dp[d_idx]
                nxt = new_dp[d_idx]
                for r in range(d):
                    val = curr[r]
                    if val:
                        nxt[(r * 10 + x) % d] += val
                nxt[x % d] += 1
            if x != 0:
                ans += new_dp[x - 1][0]
            dp = new_dp
        return ans

import math
from typing import List

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        m = len(target)
        num_masks = 1 << m

        # Precompute LCM for each non-empty subset of target
        lcms = [1] * num_masks
        for mask in range(1, num_masks):
            l = 1
            for i in range(m):
                if (mask >> i) & 1:
                    l = (l * target[i]) // math.gcd(l, target[i])
            lcms[mask] = l

        INF = float('inf')
        dp = [INF] * num_masks
        dp[0] = 0

        for x in nums:
            # Calculate cost for current x to cover each subset
            costs = [0] * num_masks
            for S in range(1, num_masks):
                L = lcms[S]
                rem = x % L
                costs[S] = 0 if rem == 0 else L - rem

            next_dp = list(dp)
            for mask in range(num_masks):
                if dp[mask] == INF:
                    continue
                cur_cost = dp[mask]
                for S in range(1, num_masks):
                    new_mask = mask | S
                    if cur_cost + costs[S] < next_dp[new_mask]:
                        next_dp[new_mask] = cur_cost + costs[S]
            dp = next_dp

        return dp[num_masks - 1]

class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        cnt = collections.defaultdict(int)
        ans = 0
        for r in range(4, n - 2):
            q = r - 2
            for p in range(q - 1):
                g = math.gcd(nums[p], nums[q])
                cnt[(nums[p] // g, nums[q] // g)] += 1
            for s in range(r + 2, n):
                g = math.gcd(nums[s], nums[r])
                ans += cnt[(nums[s] // g, nums[r] // g)]
        return ans

class Solution:
    def maxLength(self, nums: List[int]) -> int:
        ans = 0
        n = len(nums)
        for i in range(n):
            p = 1
            g = 0
            l = 1
            for j in range(i, n):
                x = nums[j]
                p *= x
                g = math.gcd(g, x)
                l = math.lcm(l, x)
                if p == l * g:
                    ans = max(ans, j - i + 1)
        return ans

class Solution:
    def countPartitions(self, nums: List[int]) -> int:
        return len(nums) - 1 if sum(nums) % 2 == 0 else 0

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        counts = collections.defaultdict(int)
        n = len(nums)
        for i in range(n - k + 1):
            for val in set(nums[i:i + k]):
                counts[val] += 1

        candidates = [val for val, count in counts.items() if count == 1]
        return max(candidates) if candidates else -1

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        zigzag = []
        for r, row in enumerate(grid):
            if r % 2 == 1:
                zigzag.extend(row[::-1])
            else:
                zigzag.extend(row)
        return zigzag[::2]

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        return any(len(list(g)) == k for _, g in itertools.groupby(s))

class Solution:
    def maximumCoins(self, coins: List[List[int]], k: int) -> int:
        def solve(intervals: List[List[int]]) -> int:
            intervals.sort(key=lambda x: x[0])
            n = len(intervals)
            ans = 0
            curr_sum = 0
            j = 0
            for i in range(n):
                while j < n and intervals[j][1] <= intervals[i][0] + k - 1:
                    curr_sum += (intervals[j][1] - intervals[j][0] + 1) * intervals[j][2]
                    j += 1
                partial = 0
                if j < n and intervals[j][0] <= intervals[i][0] + k - 1:
                    partial = (intervals[i][0] + k - 1 - intervals[j][0] + 1) * intervals[j][2]
                ans = max(ans, curr_sum + partial)
                if j > i:
                    curr_sum -= (intervals[i][1] - intervals[i][0] + 1) * intervals[i][2]
                else:
                    j = i + 1
            return ans

        ans1 = solve(coins)
        reflected = [[-r, -l, c] for l, r, c in coins]
        ans2 = solve(reflected)
        return max(ans1, ans2)

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        MAX_V = 301
        dp = [[0] * MAX_V for _ in range(MAX_V)]

        for x in nums:
            cur = [0] * MAX_V
            for v in range(1, MAX_V):
                if dp[v][0] > 0:
                    d = abs(x - v)
                    length = dp[v][d] + 1
                    if length > cur[d]:
                        cur[d] = length

            running_max = 1
            for d in range(MAX_V - 1, -1, -1):
                if cur[d] > running_max:
                    running_max = cur[d]
                if running_max > dp[x][d]:
                    dp[x][d] = running_max

        return max(dp[v][0] for v in range(MAX_V))

