class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        events.sort(key=lambda x: (int(x[1]), 0 if x[0] == "OFFLINE" else 1))

        mentions = [0] * numberOfUsers
        online_time = [0] * numberOfUsers

        for event_type, timestamp_str, data in events:
            t = int(timestamp_str)
            if event_type == "OFFLINE":
                uid = int(data)
                online_time[uid] = t + 60
            else:
                if data == "ALL":
                    for u in range(numberOfUsers):
                        mentions[u] += 1
                elif data == "HERE":
                    for u in range(numberOfUsers):
                        if online_time[u] <= t:
                            mentions[u] += 1
                else:
                    for token in data.split():
                        uid = int(token[2:])
                        mentions[uid] += 1

        return mentions

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + nums[i]

        dp = [0] * (n + 1)

        for j in range(1, k + 1):
            next_dp = [-float('inf')] * (n + 1)
            f = -float('inf')
            for i in range(j * m, n + 1):
                sub_sum = pref[i] - pref[i - m]
                f = max(f + nums[i - 1], dp[i - m] + sub_sum)
                next_dp[i] = max(next_dp[i - 1], f)
            dp = next_dp

        return dp[n]

class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total = 0
        n = len(nums)
        for i in range(n):
            is_good = True
            if i - k >= 0 and nums[i] <= nums[i - k]:
                is_good = False
            if i + k < n and nums[i] <= nums[i + k]:
                is_good = False
            if is_good:
                total += nums[i]
        return total

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        def count_pairs(L: int, R: int, M: int) -> int:
            if M < 0:
                return 0
            L = min(L, M + 1)
            R = min(R, M + 1)
            if L + R - 2 <= M:
                return L * R
            E = L + R - 2 - M
            return L * R - E * (E + 1) // 2

        def solve_max(arr: List[int]) -> int:
            n = len(arr)
            prev_greater = [-1] * n
            next_greater_or_equal = [n] * n

            stack = []
            for i in range(n):
                while stack and arr[stack[-1]] <= arr[i]:
                    next_greater_or_equal[stack.pop()] = i
                stack.append(i)

            stack = []
            for i in range(n - 1, -1, -1):
                while stack and arr[stack[-1]] < arr[i]:
                    prev_greater[stack.pop()] = i
                stack.append(i)

            total = 0
            M = k - 1
            for i in range(n):
                L = i - prev_greater[i]
                R = next_greater_or_equal[i] - i
                cnt = count_pairs(L, R, M)
                total += arr[i] * cnt
            return total

        return solve_max(nums) - solve_max([-x for x in nums])

class Solution:
    def subarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + nums[i]

        total = 0
        for i in range(n):
            start = max(0, i - nums[i])
            total += pref[i + 1] - pref[start]

        return total

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # dp[d][t][r][c] stores the max straight path length starting at (r, c)
        # in direction d, expecting value t (0 or 2) alternating.
        # To map t in {0, 2}: index 0 for 0, index 1 for 2.
        # Next target value for v is 2 - v.
        dp = [[[[0] * m for _ in range(n)] for _ in range(2)] for _ in range(4)]

        def target_idx(val: int) -> int:
            return 0 if val == 0 else 1

        for d, (dr, dc) in enumerate(dirs):
            r_range = range(n - 1, -1, -1) if dr > 0 else range(n)
            c_range = range(m - 1, -1, -1) if dc > 0 else range(m)
            for r in r_range:
                for c in c_range:
                    val = grid[r][c]
                    if val == 0 or val == 2:
                        t_idx = target_idx(val)
                        nr, nc = r + dr, c + dc
                        nxt_val = 2 - val
                        nxt_t_idx = target_idx(nxt_val)
                        if 0 <= nr < n and 0 <= nc < m:
                            dp[d][t_idx][r][c] = 1 + dp[d][nxt_t_idx][nr][nc]
                        else:
                            dp[d][t_idx][r][c] = 1

        has_one = False
        ans = 0

        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    has_one = True
                    for d, (dr, dc) in enumerate(dirs):
                        # Option 1: No turn
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            ans = max(ans, 1 + dp[d][target_idx(2)][nr][nc])

                        # Option 2: Walk k steps in direction d, then turn clockwise
                        cur_r, cur_c = r + dr, c + dc
                        expected = 2
                        step = 1
                        d_turn = (d + 1) % 4
                        tdr, tdc = dirs[d_turn]

                        while 0 <= cur_r < n and 0 <= cur_c < m and grid[cur_r][cur_c] == expected:
                            # From (cur_r, cur_c), we can turn to d_turn
                            next_turn_r, next_turn_c = cur_r + tdr, cur_c + tdc
                            next_expected = 2 - expected
                            turn_len = 0
                            if 0 <= next_turn_r < n and 0 <= next_turn_c < m:
                                turn_len = dp[d_turn][target_idx(next_expected)][next_turn_r][next_turn_c]
                            ans = max(ans, 1 + step + turn_len)

                            cur_r += dr
                            cur_c += dc
                            expected = 2 - expected
                            step += 1

        if not has_one:
            return 0
        return max(ans, 1)

class Solution:
    def findValidPair(self, s: str) -> str:
        count = collections.Counter(s)
        for i in range(len(s) - 1):
            c1, c2 = s[i], s[i + 1]
            if c1 != c2 and count[c1] == int(c1) and count[c2] == int(c2):
                return c1 + c2
        return ""

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        dp = [[float('inf')] * 3 for _ in range(3)]
        for c1 in range(3):
            for c2 in range(3):
                if c1 != c2:
                    dp[c1][c2] = cost[0][c1] + cost[n - 1][c2]

        for i in range(1, n // 2):
            new_dp = [[float('inf')] * 3 for _ in range(3)]
            for c1 in range(3):
                for c2 in range(3):
                    if c1 == c2:
                        continue
                    best = float('inf')
                    for pc1 in range(3):
                        if pc1 == c1:
                            continue
                        for pc2 in range(3):
                            if pc2 == c2:
                                continue
                            if dp[pc1][pc2] < best:
                                best = dp[pc1][pc2]
                    new_dp[c1][c2] = best + cost[i][c1] + cost[n - 1 - i][c2]
            dp = new_dp

        return min(dp[c1][c2] for c1 in range(3) for c2 in range(3))

class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
        n = len(startTime)
        gaps = [startTime[0]] + [startTime[i] - endTime[i - 1] for i in range(1, n)] + [eventTime - endTime[-1]]

        window_size = k + 1
        cur_sum = sum(gaps[:window_size])
        max_free = cur_sum

        for i in range(window_size, len(gaps)):
            cur_sum += gaps[i] - gaps[i - window_size]
            if cur_sum > max_free:
                max_free = cur_sum

        return max_free

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def F(n: int) -> int:
            if n <= 0:
                return 0
            res = 0
            p = 1
            k = 1
            while p <= n:
                next_p = p * 4
                count = min(n, next_p - 1) - p + 1
                res += count * k
                p = next_p
                k += 1
            return res

        ans = 0
        for l, r in queries:
            s = F(r) - F(l - 1)
            ans += (s + 1) // 2
        return ans

class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        return max(abs(nums[i] - nums[(i + 1) % len(nums)]) for i in range(len(nums)))

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        for r in range(n):
            vals = []
            k = 0
            while r + k < n and k < n:
                vals.append(grid[r + k][k])
                k += 1
            vals.sort(reverse=True)
            k = 0
            while r + k < n and k < n:
                grid[r + k][k] = vals[k]
                k += 1

        for c in range(1, n):
            vals = []
            k = 0
            while k < n and c + k < n:
                vals.append(grid[k][c + k])
                k += 1
            vals.sort()
            k = 0
            while k < n and c + k < n:
                grid[k][c + k] = vals[k]
                k += 1

        return grid

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        initial_k = nums.count(k)
        max_gain = 0
        unique_vals = set(nums)
        unique_vals.discard(k)

        for v in unique_vals:
            cur = 0
            best = 0
            for x in nums:
                if x == v:
                    cur += 1
                elif x == k:
                    cur -= 1
                if cur < 0:
                    cur = 0
                if cur > best:
                    best = cur
            if best > max_gain:
                max_gain = best

        return initial_k + max_gain

class Solution:
    def maxDifference(self, s: str) -> int:
        counts = Counter(s).values()
        odd_freqs = [c for c in counts if c % 2 == 1]
        even_freqs = [c for c in counts if c % 2 == 0]
        return max(odd_freqs) - min(even_freqs)

class Solution: 
    def maxDistance(self, s: str, k: int) -> int:
        ans = 0
        cN = cS = cE = cW = 0
        for t, ch in enumerate(s, 1):
            if ch == 'N':
                cN += 1
            elif ch == 'S':
                cS += 1
            elif ch == 'E':
                cE += 1
            elif ch == 'W':
                cW += 1
            d = abs(cE - cW) + abs(cN - cS)
            ans = max(ans, min(t, d + 2 * k))
        return ans

class Solution:
    def findMaxSum(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        n = len(nums1)
        ans = [0] * n

        items = sorted([(nums1[i], nums2[i], i) for i in range(n)], key=lambda x: x[0])

        min_heap = []
        current_sum = 0

        i = 0
        while i < n:
            j = i
            while j < n and items[j][0] == items[i][0]:
                ans[items[j][2]] = current_sum
                j += 1

            for idx in range(i, j):
                val = items[idx][1]
                if len(min_heap) < k:
                    heapq.heappush(min_heap, val)
                    current_sum += val
                elif min_heap and val > min_heap[0]:
                    current_sum += val - min_heap[0]
                    heapq.heapreplace(min_heap, val)

            i = j

        return ans

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_val = max(groups)
        min_idx = [-1] * (max_val + 1)
        seen = {}

        for j, e in enumerate(elements):
            if e <= max_val and e not in seen:
                seen[e] = j

        for e, j in seen.items():
            for multiple in range(e, max_val + 1, e):
                if min_idx[multiple] == -1 or j < min_idx[multiple]:
                    min_idx[multiple] = j

        return [min_idx[g] for g in groups]

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        if m < n:
            return 0

        def check(x: int) -> bool:
            req = [(x + p - 1) // p for p in points]
            moves = 1
            c = 0

            for i in range(n - 1):
                visits = 1 + c if i > 0 else 1
                k = max(0, req[i] - visits)
                moves += 2 * k
                c = k

                if i == n - 2:
                    if req[n - 1] <= c:
                        break
                    moves += 1
                    k_last = max(0, req[n - 1] - (c + 1))
                    moves += 2 * k_last
                else:
                    moves += 1

                if moves > m:
                    return False

            return moves <= m

        low = 0
        high = (m + 1) * max(points) // 2 + 1
        ans = 0

        while low <= high:
            mid = (low + high) // 2
            if mid == 0 or check(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1

        return ans

class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        candidates = []
        for row, limit in zip(grid, limits):
            if limit > 0:
                row.sort(reverse=True)
                candidates.extend(row[:limit])
        candidates.sort(reverse=True)
        return sum(candidates[:k])

class Solution:
    def hasSameDigits(self, s: str) -> bool:
