        while len(nums) > 2:
            nums = [(nums[i] + nums[i + 1]) % 10 for i in range(len(nums) - 1)]
        return nums[0] == nums[1]

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        total_len = n + m - 1

        word = [None] * total_len

        # Step 1: Apply all 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    if word[i + j] is not None and word[i + j] != str2[j]:
                        return ""
                    word[i + j] = str2[j]

        # Step 2: Analyze 'F' constraints
        mismatches = [0] * n
        free_count = [0] * n
        last_free = [-1] * n
        intervals_ending_at = [[] for _ in range(total_len)]

        for i in range(n):
            if str1[i] == 'F':
                for j in range(m):
                    pos = i + j
                    if word[pos] is None:
                        free_count[i] += 1
                        last_free[i] = pos
                    elif word[pos] != str2[j]:
                        mismatches[i] += 1

                if free_count[i] == 0 and mismatches[i] == 0:
                    return ""
                if free_count[i] > 0:
                    intervals_ending_at[last_free[i]].append(i)

        # Step 3: Greedily determine characters for free positions
        for k in range(total_len):
            if word[k] is None:
                forbidden = set()
                for i in intervals_ending_at[k]:
                    if mismatches[i] == 0:
                        forbidden.add(str2[k - i])

                for code in range(ord('a'), ord('z') + 1):
                    c = chr(code)
                    if c not in forbidden:
                        word[k] = c
                        break

                # Update mismatches for intervals covering k
                for i in range(max(0, k - m + 1), min(n, k + 1)):
                    if str1[i] == 'F':
                        if word[k] != str2[k - i]:
                            mismatches[i] += 1

        return "".join(word)

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True

        n = len(s)
        first = {}
        last = {}
        for i, ch in enumerate(s):
            if ch not in first:
                first[ch] = i
            last[ch] = i

        intervals = []
        for ch in first:
            l = first[ch]
            r = last[ch]
            valid = True
            i = l
            while i <= r:
                curr_ch = s[i]
                if first[curr_ch] < l:
                    valid = False
                    break
                r = max(r, last[curr_ch])
                i += 1

            if valid and not (l == 0 and r == n - 1):
                intervals.append((l, r))

        intervals.sort(key=lambda x: x[1])

        count = 0
        prev_end = -1
        for l, r in intervals:
            if l > prev_end:
                count += 1
                prev_end = r

        return count >= k

class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        def is_non_decreasing(arr):
            for i in range(len(arr) - 1):
                if arr[i] > arr[i + 1]:
                    return False
            return True

        ops = 0
        while not is_non_decreasing(nums):
            min_sum = float('inf')
            min_idx = -1
            for i in range(len(nums) - 1):
                s = nums[i] + nums[i + 1]
                if s < min_sum:
                    min_sum = s
                    min_idx = i
            nums = nums[:min_idx] + [min_sum] + nums[min_idx + 2:]
            ops += 1
        return ops

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]
        if n == 2:
            return max(nums[0], nums[1])

        if n % 2 == 1:
            dp = [nums[p] for p in range(n)]
            last_i = n - 2
        else:
            dp = [max(nums[p], nums[n - 1]) for p in range(n)]
            last_i = n - 3

        for i in range(last_i, 0, -2):
            next_dp = [0] * i
            a = nums[i]
            b = nums[i + 1]
            max_ab = max(a, b)
            for p in range(i):
                val1 = max_ab + dp[p]
                val2 = max(nums[p], b) + dp[i]
                val3 = max(nums[p], a) + dp[i + 1]
                next_dp[p] = min(val1, val2, val3)
            dp = next_dp

        return dp[0]

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        if abs(k) > 150 * 12:
            return -1

        dp0 = collections.defaultdict(set)  # even length subsequences
        dp1 = collections.defaultdict(set)  # odd length subsequences

        for x in nums:
            add0 = collections.defaultdict(set)
            add1 = collections.defaultdict(set)

            if x <= limit:
                add1[x].add(x)

            for s, prods in dp0.items():
                ns = s + x
                for p in prods:
                    np = p * x
                    if np <= limit:
                        add1[ns].add(np)

            for s, prods in dp1.items():
                ns = s - x
                for p in prods:
                    np = p * x
                    if np <= limit:
                        add0[ns].add(np)

            for s, prods in add0.items():
                dp0[s].update(prods)
            for s, prods in add1.items():
                dp1[s].update(prods)

        res_prods = dp0[k] | dp1[k]
        return max(res_prods) if res_prods else -1

class Solution:
    def transformArray(self, nums: List[int]) -> List[int]:
        return sorted(x % 2 for x in nums)

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def get_pos(p: List[int]) -> int:
            x, y = p
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 3 * side - x
            else:
                return 4 * side - y

        points.sort(key=get_pos)
        n = len(points)

        def dist(p1: List[int], p2: List[int]) -> int:
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        def check(d: int) -> bool:
            next_hop = [-1] * n
            j = 0
            for i in range(n):
                j = max(j, i + 1)
                while j < i + n and dist(points[i], points[j % n]) < d:
                    j += 1
                if j < i + n:
                    next_hop[i] = j
                else:
                    next_hop[i] = -1

            if next_hop[0] == -1:
                return False

            limit = min(next_hop[0], n - 1)
            for start in range(limit + 1):
                curr = start
                possible = True
                for _ in range(k - 1):
                    nxt = next_hop[curr % n]
                    if nxt == -1:
                        possible = False
                        break
                    curr = curr + (nxt - (curr % n))
                    if curr >= start + n:
                        possible = False
                        break
                if possible and dist(points[curr % n], points[start]) >= d:
                    return True
            return False

        low, high = 1, side
        ans = 1
        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1

        return ans

import math
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = [x for x in range(1, n + 1) if x % 2 == 1]
        evens = [x for x in range(1, n + 1) if x % 2 == 0]

        if n % 2 == 1:
            total = math.factorial(len(odds)) * math.factorial(len(evens))
        else:
            total = 2 * math.factorial(len(odds)) * math.factorial(len(evens))

        if k > total:
            return []

        res = []
        for p in range(n):
            if p == 0:
                if n % 2 == 1:
                    candidates = [(x, 1) for x in odds]
                else:
                    candidates = sorted([(x, 1) for x in odds] + [(x, 0) for x in evens])
            else:
                req_parity = 1 - (res[-1] % 2)
                if req_parity == 1:
                    candidates = [(x, 1) for x in odds]
                else:
                    candidates = [(x, 0) for x in evens]

            for x, par in candidates:
                if par == 1:
                    ways = math.factorial(len(odds) - 1) * math.factorial(len(evens))
                else:
                    ways = math.factorial(len(odds)) * math.factorial(len(evens) - 1)

                if k <= ways:
                    res.append(x)
                    if par == 1:
                        odds.remove(x)
                    else:
                        evens.remove(x)
                    break
                else:
                    k -= ways

        return res

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        # Build Trie
        # Each node: children dict, count, depth
        trie = [{'children': {}, 'count': 0, 'depth': 0}]

        for word in words:
            curr = 0
            trie[curr]['count'] += 1
            for ch in word:
                if ch not in trie[curr]['children']:
                    trie.append({'children': {}, 'count': 0, 'depth': trie[curr]['depth'] + 1})
                    trie[curr]['children'][ch] = len(trie) - 1
                curr = trie[curr]['children'][ch]
                trie[curr]['count'] += 1

        num_nodes = len(trie)
        tin = [0] * num_nodes
        tout = [0] * num_nodes
        timer = 0

        # Iterative DFS to compute tin and tout
        stack = [(0, False)]
        while stack:
            u, visited = stack.pop()
            if visited:
                tout[u] = timer - 1
            else:
                tin[u] = timer
                timer += 1
                stack.append((u, True))
                for ch, v in trie[u]['children'].items():
                    stack.append((v, False))

        pref_max = [0] * (timer + 1)
        suff_max = [0] * (timer + 1)

        for u in range(num_nodes):
            if trie[u]['count'] >= k:
                d = trie[u]['depth']
                L = tin[u] - 1
                R = tout[u] + 1
                if L >= 0:
                    if d > pref_max[L]:
                        pref_max[L] = d
                if R < timer:
                    if d > suff_max[R]:
                        suff_max[R] = d

        for i in range(timer - 2, -1, -1):
            if pref_max[i + 1] > pref_max[i]:
                pref_max[i] = pref_max[i + 1]

        for i in range(1, timer):
            if suff_max[i - 1] > suff_max[i]:
                suff_max[i] = suff_max[i - 1]

        ans = [0] * n
        for i, word in enumerate(words):
            curr = 0
            path_max = 0
            for ch in word:
                curr = trie[curr]['children'][ch]
                if trie[curr]['count'] >= k + 1:
                    path_max = max(path_max, trie[curr]['depth'])

            leaf_t = tin[curr]
            outside_max = max(pref_max[leaf_t], suff_max[leaf_t])
            ans[i] = max(path_max, outside_max)

        return ans

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        min_c = -float('inf')
        max_c = float('inf')
        for orig, (u, v) in zip(original, bounds):
            min_c = max(min_c, u - orig)
            max_c = min(max_c, v - orig)
        return max(0, max_c - min_c + 1)

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        dp = [[[0] * (k + 1) for _ in range(n)] for _ in range(n)]

        for i in range(n):
            for c in range(k + 1):
                dp[i][i][c] = 1

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                diff = abs(ord(s[i]) - ord(s[j]))
                cost = min(diff, 26 - diff)

                dp_ij = dp[i][j]
                dp_next_i = dp[i + 1][j]
                dp_prev_j = dp[i][j - 1]
                dp_inner = dp[i + 1][j - 1] if length > 2 else None

                for c in range(k + 1):
                    res = dp_next_i[c] if dp_next_i[c] > dp_prev_j[c] else dp_prev_j[c]
                    if c >= cost:
                        match_val = (dp_inner[c - cost] if dp_inner is not None else 0) + 2
                        if match_val > res:
                            res = match_val
                    dp_ij[c] = res

        return dp[0][n - 1][k]

class Solution:
    def maxSum(self, nums: List[int]) -> int:
        mx = max(nums)
        if mx < 0:
            return mx
        return sum(x for x in set(nums) if x > 0)

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        pairs_at = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            u, v = min(a, b), max(a, b)
            pairs_at[v].append((u, i))

        m = len(conflictingPairs)
        gain = [0] * m
        base_sum = 0

        max1_u, max1_id = 0, -1
        max2_u = 0

        for r in range(1, n + 1):
            for u, idx in pairs_at[r]:
                if u > max1_u:
                    max2_u = max1_u
                    max1_u, max1_id = u, idx
                elif u == max1_u:
                    max2_u = u
                    max1_id = -1
                elif u > max2_u:
                    max2_u = u

            base_sum += r - max1_u
            if max1_id != -1:
                gain[max1_id] += max1_u - max2_u

        return base_sum + (max(gain) if gain else 0)

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        size = 1
        while size < n:
            size *= 2
        tree = [0] * (2 * size)
        for i in range(n):
            tree[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[2 * i], tree[2 * i + 1])

        unplaced = 0
        for x in fruits:
            if tree[1] < x:
                unplaced += 1
                continue
            node = 1
            while node < size:
                if tree[2 * node] >= x:
                    node = 2 * node
                else:
                    node = 2 * node + 1
            tree[node] = 0
            node //= 2
            while node > 0:
                tree[node] = max(tree[2 * node], tree[2 * node + 1])
                node //= 2

        return unplaced

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        subs_s = [""] + [s[i:j] for i in range(len(s)) for j in range(i + 1, len(s) + 1)]
        subs_t = [""] + [t[i:j] for i in range(len(t)) for j in range(i + 1, len(t) + 1)]

        ans = 0
        for sub1 in subs_s:
            for sub2 in subs_t:
                if len(sub1) + len(sub2) <= ans:
                    continue
                cand = sub1 + sub2
                if cand == cand[::-1]:
                    ans = len(cand)
        return ans

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        min_k = [0] * n

        for j in range(n):
            target = nums[j]
            if target == 0:
                continue

            dp = 1
            found = False
            for k, (l, r, val) in enumerate(queries, 1):
                if l <= j <= r:
                    dp |= (dp << val)
                    if (dp >> target) & 1:
                        min_k[j] = k
                        found = True
                        break
            if not found:
                return -1

        return max(min_k)

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
