from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(n: int) -> int:
            if n <= 0:
                return 0
            s_n = str(n)
            digits = [int(c) for c in s_n]
            n_digits = len(digits)
            max_sum = 9 * n_digits

            total = 0
            for S in range(1, max_sum + 1):
                @lru_cache(None)
                def dp(idx: int, is_less: bool, is_started: bool, cur_sum: int, cur_prod: int) -> int:
                    if cur_sum > S:
                        return 0
                    if idx == n_digits:
                        return 1 if (is_started and cur_sum == S and cur_prod == 0) else 0

                    limit = 9 if is_less else digits[idx]
                    ans = 0
                    for d in range(limit + 1):
                        nxt_less = is_less or (d < limit)
                        if not is_started:
                            if d == 0:
                                ans += dp(idx + 1, True, False, 0, 1 % S)
                            else:
                                ans += dp(idx + 1, nxt_less, True, d, d % S)
                        else:
                            ans += dp(idx + 1, nxt_less, True, cur_sum + d, (cur_prod * d) % S)
                    return ans

                total += dp(0, False, False, 0, 1 % S)
            return total

        return count(r) - count(l - 1)

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        # Find all 0-blocks and 1-blocks
        n = len(s)
        initial_ones = s.count('1')

        # Group consecutive characters
        groups = []
        for char, group in itertools.groupby(s):
            groups.append((char, len(list(group))))

        zeros = []
        ones_between = []

        for i, (char, length) in enumerate(groups):
            if char == '0':
                zeros.append(length)
            else:
                # A 1-block is strictly between two 0-blocks if it's not the first or last group
                if 0 < i < len(groups) - 1:
                    ones_between.append(length)

        k = len(zeros)
        if k < 2:
            return initial_ones

        # Prefix and suffix max of zeros
        pref_max = [0] * (k + 1)
        for i in range(k):
            pref_max[i + 1] = max(pref_max[i], zeros[i])

        suff_max = [0] * (k + 1)
        for i in range(k - 1, -1, -1):
            suff_max[i] = max(suff_max[i + 1], zeros[i])

        best_gain = 0
        for i in range(k - 1):
            z_sum = zeros[i] + zeros[i + 1]
            o_len = ones_between[i]

            # Max of zeros not in {i, i+1}
            other_max = max(pref_max[i], suff_max[i + 2])
            gain = max(z_sum, other_max - o_len)
            if gain > best_gain:
                best_gain = gain

        return initial_ones + best_gain

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        sets = [set(row) for row in properties]
        parent = list(range(n))

        def find(i):
            if parent[i] != i:
                parent[i] = find(parent[i])
            return parent[i]

        components = n
        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    root_i = find(i)
                    root_j = find(j)
                    if root_i != root_j:
                        parent[root_i] = root_j
                        components -= 1

        return components

class Solution:
    def reverseDegree(self, s: str) -> int:
